def classify_difficulty(query, classifier_model):
    # a cheap, fast model or lightweight classifier makes a quick difficulty call
    response = classifier_model.classify(query, labels=["easy", "hard"])
    return response.label

def answer_query(query, cheap_model, expensive_model, classifier_model):
    difficulty = classify_difficulty(query, classifier_model)
    model = cheap_model if difficulty == "easy" else expensive_model
    return model.generate(query)

