def process_request(user_input, model, input_filters, output_filters):
    for check in input_filters:
        if check.is_flagged(user_input):
            return f"Request blocked: {check.reason}"

    raw_output = model.generate(user_input)

    for check in output_filters:
        if check.is_flagged(raw_output):
            return "I can't share that response -- let me connect you with a human agent."

    return raw_output

threshold_results = {
    0.30: {"precision": 0.62, "recall": 0.97},   # low threshold (loose): flags aggressively, catches nearly everything unsafe, blocks a lot of fine content too
    0.60: {"precision": 0.85, "recall": 0.88},   # a middle ground
    0.90: {"precision": 0.97, "recall": 0.61},   # high threshold (strict): rarely wrongly blocks fine content, but misses more real violations
}

for threshold, scores in threshold_results.items():
    print(f"threshold={threshold}: precision={scores['precision']}, recall={scores['recall']}")
# Recall here = fraction of genuinely unsafe outputs the filter actually catches.
# There is no threshold in this table with BOTH precision and recall near 1.0.

